 if(id==='admin:verification:saveRaidLimits'){const thresholdRaw=i.fields.getTextInputValue('joinThreshold').trim(),windowRaw=i.fields.getTextInputValue('windowSeconds').trim();if(!/^\d+$/.test(thresholdRaw)||!/^\d+$/.test(windowRaw))throw new Error('Raid limits must be whole numbers.');const joinThreshold=Number(thresholdRaw),windowSeconds=Number(windowRaw);if(!Number.isSafeInteger(joinThreshold)||joinThreshold<2||joinThreshold>10000||!Number.isSafeInteger(windowSeconds)||windowSeconds<5||windowSeconds>3600)throw new Error('Use 2–10000 joins and a 5–3600 second window.');const c=settings(i.guildId);save(i.guildId,{raid:{...(c.raid||{}),joinThreshold,windowSeconds}},i.user.id);await i.reply({content:`✅ Raid limits saved: ${joinThreshold} joins in ${windowSeconds} seconds. Reopen Verification Settings to view the updated limits.`,flags:64});return true;}
